import type {IncomingMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validate = validators[message.type];
  return validate ? validate(message) : {valid: false, error: `Unknown message type: ${message.type}`};
}

const validators: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  user_message: validateUserMessage,
  ping: validatePingMessage,
  list_sessions: validateListSessionsMessage,
};

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = message.limit;
  if (!isValidLimit(limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  const beforeError = cursorError(message.before);
  if (beforeError) {
    return {valid: false, error: beforeError};
  }

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      ...(limit === undefined ? {} : {limit}),
      ...(message.before === undefined
        ? {}
        : {
            before: {
              sessionId: (message.before as Record<string, unknown>).sessionId as string,
              updatedAt: (message.before as Record<string, unknown>).updatedAt as string | number,
            },
          }),
    },
  };
}

function isValidLimit(limit: unknown): limit is number | undefined {
  return limit === undefined || (typeof limit === 'number' && Number.isInteger(limit) && limit >= 0);
}

function cursorError(value: unknown): string | undefined {
  if (value === undefined) return undefined;
  if (!isRecord(value)) return 'list_sessions before must be a cursor object';
  if (!isValidSessionId(value.sessionId)) return 'list_sessions before sessionId must be 1-128 characters';
  return isValidCursorTime(value.updatedAt) ? undefined : 'list_sessions before updatedAt must be a valid timestamp';
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isValidSessionId(value: unknown): value is string {
  return typeof value === 'string' && value.length > 0 && value.length <= 128;
}

/** Opens a client that the suite's teardown will close, whether its test passed or failed. */
export function connectClient(url: string, token = 't'): WebSocket {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
  clients.push(client);
  return client;
}

/** Sends a frame after `connected` and collects every reply before the ping barrier's `pong`. */
export function askAfterConnect<T extends {type: string}>(
  url: string,
  outbound: unknown
): Promise<{connected: T; frames: T[]}> {
  const client = connectClient(url);
  const frames: T[] = [];
  let connected = {type: ''} as T;
  return new Promise(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as T;
      if (frame.type !== 'connected') {
        if (frame.type === 'pong') return resolve({connected, frames});
        frames.push(frame);
        return;
      }
      connected = frame;
      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
    });
  });
}

/** A promise a test settles by hand, to hold a stream or a hook at a point of its choosing. */
export function deferred(): {until: Promise<void>; release: () => void} {
  let release = (): void => undefined;
  const until = new Promise<void>(resolve => {
    release = resolve;
  });
  return {until, release};
}

import type {
  ConversationCursor,
  IncomingMessage,
  OutgoingMessage,
  SessionListMessage,
  SessionSummaryFrame,
} from './messages.js';
import {ErrorCodes} from './messages.js';

describe('conversation list protocol frames', () => {
  // specs/hal-engine-conversation-list/spec.md#74
  it('exports list session request and response frames through the public message unions', () => {
    const request: IncomingMessage = {
      type: 'list_sessions',
      limit: 2,
      before: {sessionId: 'earlier', updatedAt: '2026-10-31T10:00:00.000Z'},
    };
    const summary: SessionSummaryFrame = {
      sessionId: 'earlier',
      createdAt: '2026-10-31T09:00:00.000Z',
      updatedAt: '2026-10-31T10:00:00.000Z',
      entryCount: 3,
    };
    const response: OutgoingMessage = {type: 'session_list', sessions: [summary]};
    const cursor: ConversationCursor = summary;
    const listed: SessionListMessage = response as SessionListMessage;

    expect({request, cursor, listed}).toEqual({
      request,
      cursor: summary,
      listed: response,
    });
    expect(ErrorCodes.INVALID_MESSAGE).toBe('INVALID_MESSAGE');
  });
});

